"""Text statistics."""

from collections import Counter

from wordstat.tokens import sentences, words


def word_count(text: str) -> int:
    """Number of words in text."""
    return len(words(text))


def longest_word(text: str) -> str:
    """The longest word, the first one on ties, or '' for empty text."""
    return max(words(text), key=len, default="")


def average_word_length(text: str) -> float:
    """Mean word length in letters, rounded to one decimal."""
    ws = words(text)
    if not ws:
        return 0.0
    return round(sum(len(w) for w in ws) / len(ws), 1)


STOPWORDS = frozenset({"a", "an", "and", "in", "is", "it", "of", "the", "to"})


def top_words(text: str, n: int, skip_stopwords: bool = False) -> dict[str, int]:
    """The n most common words mapped to their counts, most common first."""
    ws = words(text)
    if skip_stopwords:
        ws = [w for w in ws if w not in STOPWORDS]
    return dict(Counter(ws).most_common(n))


def words_per_sentence(text: str) -> float:
    """Average sentence length in words, rounded to one decimal."""
    ss = sentences(text)
    if not ss:
        return 0.0
    return round(word_count(text) / len(ss), 1)


def unique_words(text: str) -> int:
    """Number of distinct lower-cased words."""
    return len(set(words(text)))

